  for c in lower.split("") {
    if c.len() == 1 {
      let b = c.to_bytes()[0];
      if b >= 97 && b <= 122 {
        word = word + c;
      } else {
        if word.len() > 0 {
          let cur = counts.get(word).unwrap_or(0);
          counts.insert(word, cur + 1);
          word = "";
        }
      }
    }
  }
  if word.len() > 0 {
    let cur = counts.get(word).unwrap_or(0);
    counts.insert(word, cur + 1);
  }
  let mut pairs: List<Str> = [];
  for w in counts.keys() {
    let c = counts.get(w).unwrap_or(0);
    pairs.push(c.to_str() + " " + w);
  }
  let mut keyed: List<Str> = [];
  for p in pairs {
    keyed.push(p);
  }
  let mut ranked: List<Int> = [];
  let mut out = "";
  let mut k = 0;
  while k < 5 && k < keyed.len() {
    out = out + keyed[k] + "\n";
    k = k + 1;
  }
  Ok(out)
}

fn is_letter(b: Int) -> Bool {
  (b >= 97 && b <= 122) || (b >= 65 && b <= 90)
}

fn lower_byte(b: Int) -> Int {
  if b >= 65 && b <= 90 { b + 32 } else { b }
}

