struct Entry { word: Str, count: Int }

fn is_letter(b: Int) -> Bool {
  (b >= 97 && b <= 122) || (b >= 65 && b <= 90)
}

fn lower_byte(b: Int) -> Int {
  if b >= 65 && b <= 90 { b + 32 } else { b }
}

fn main(input: Dir) -> Result<Str, IoErr> {
  let raw = input.read("text.txt")?;
  let n = raw.len();
  let mut counts: Map<Str, Int> = Map::new();
  let mut word: Bytes = "".to_bytes();
  let mut i = 0;
  while i < n {
    let b = raw[i];
    if is_letter(b) {
      word.push(lower_byte(b));
    } else if word.len() > 0 {
      let w = word.to_str();
      let cur = counts.get(w).unwrap_or(0);
      counts.insert(w, cur + 1);
      word = "".to_bytes();
    }
    i = i + 1;
  }
  if word.len() > 0 {
    let w = word.to_str();
    let cur = counts.get(w).unwrap_or(0);
    counts.insert(w, cur + 1);
  }
  let mut entries: List<Entry> = [];
  for w in counts.keys() {
    let c = counts.get(w).unwrap_or(0);
    entries.push(Entry { word: w, count: c });
  }
  entries.sort_by(|a, b| a.count > b.count || (a.count == b.count && a.word < b.word));
  let mut out = "";
  let mut k = 0;
  while k < 5 && k < entries.len() {
    let e = entries[k];
    out = out + e.word + " " + e.count.to_str() + "\n";
    k = k + 1;
  }
  Ok(out)
}

struct Agg { region: Str, qty: Int, cents: Int }

fn money(c: Int) -> Str {
  let a = if c < 0 { 0 - c } else { c };
  let frac = a % 100;
  let fs = if frac < 10 { "0" + frac.to_str() } else { frac.to_str() };
  let sign = if c < 0 { "-" } else { "" };
  sign + (a / 100).to_str() + "." + fs
}

fn main(input: Dir) -> Result<Str, IoErr> {
  let text = input.read("sales.csv")?.to_str();
  let mut qtys: Map<Str, Int> = Map::new();
  let mut cents: Map<Str, Int> = Map::new();
  let mut skipped = 0;
  let mut header_seen = false;
  for raw in text.lines() {
    let t = raw.trim();
    if t.len() == 0 { continue; }
    if !header_seen { header_seen = true; continue; }
    let fields = t.split(",");
    if fields.len() != 5 { skipped += 1; continue; }
    let region = fields[1].trim();
    let Some(q) = fields[3].trim().parse_int() else { skipped += 1; continue; };
    let Some(u) = fields[4].trim().parse_int() else { skipped += 1; continue; };
    let old_q = qtys.get(region).unwrap_or(0);
    let old_c = cents.get(region).unwrap_or(0);
    qtys.insert(region, old_q + q);
    cents.insert(region, old_c + q * u);
  }
  let mut aggs: List<Agg> = [];
  for r in qtys.keys() {
    aggs.push(Agg { region: r, qty: qtys.get(r).unwrap_or(0), cents: cents.get(r).unwrap_or(0) });
  }
  aggs.sort_by(|a: Agg, b: Agg| a.cents > b.cents || (a.cents == b.cents && a.region < b.region));
  let mut out = "";
  for a in aggs {
    out = out + a.region + " " + a.qty.to_str() + " " + money(a.cents) + "\n";
  }
  out = out + "skipped " + skipped.to_str();
  Ok(out)
}

struct Hit { ip: Str, n: Int }

fn main(input: Dir) -> Result<Str, IoErr> {
  let text = input.read("access.log")?.to_str();
  let mut statuses: Map<Int, Int> = Map::new();
  let mut paths: Map<Str, Int> = Map::new();
  let mut server_errs: Map<Str, Int> = Map::new();
  let mut bytes: Int = 0;

  for line in text.lines() {
    let parts = line.split("\"");
    if parts.len() < 3 { continue; }

    let head = parts[0].split(" ");
    let ip = head[0];
    if ip == "" { continue; }

    let words = parts[1].split(" ");
    if words.len() < 2 { continue; }

    let rest = parts[2].trim().split(" ");
    if rest.len() != 2 { continue; }

    let Some(status) = rest[0].parse_int() else { continue; };

    let mut size: Int = 0;
    if rest[1] != "-" {
      let Some(n) = rest[1].parse_int() else { continue; };
      size = n;
    }

    let before = paths.get(words[1].split("?")[0]).unwrap_or(0);
    let path = words[1].split("?")[0];
    let sc = statuses.get(status).unwrap_or(0);
    statuses.insert(status, sc + 1);
    bytes = bytes + size;

    let pc = paths.get(path).unwrap_or(0);
    paths.insert(path, pc + 1);

    if status >= 500 && status < 600 {
      let ec = server_errs.get(ip).unwrap_or(0);
      server_errs.insert(ip, ec + 1);
    }
  }

  let mut out: List<Str> = [];
  for s in statuses.keys() {
    let c = statuses.get(s).unwrap_or(0);
    out.push(s.to_str() + " " + c.to_str());
  }
  out.push("bytes " + bytes.to_str());

  let mut top_path: Str = "";
  let mut top_n: Int = 0;
  for p in paths.keys() {
    let c = paths.get(p).unwrap_or(0);
    if c > top_n {
      top_n = c;
      top_path = p;
    }
  }
  if top_n > 0 {
    out.push("top " + top_path + " " + top_n.to_str());
  }

  let mut hits: List<Hit> = [];
  for ip in server_errs.keys() {
    hits.push(Hit { ip: ip, n: server_errs.get(ip).unwrap_or(0) });
  }
  hits.sort_by(|a, b| a.n > b.n || (a.n == b.n && a.ip < b.ip));
  for h in hits {
    out.push("errors " + h.ip + " " + h.n.to_str());
  }

  Ok(out.join("\n"))
}

fn order_total(o: Json) -> Int {
  let mut sum = 0;
  let items: List<Json> = match o.get("items").and_then(|j| j.as_list()) {
    Some(l) => l,
    None => [],
  };
  for it in items {
    let q = it.get("qty").and_then(|j| j.as_int()).unwrap_or(0);
    let p = it.get("price_cents").and_then(|j| j.as_int()).unwrap_or(0);
    sum = sum + q * p;
  }
  sum
}

fn main(input: Dir) -> Result<Str, Str> {
  let bytes = match input.read("orders.json") {
    Ok(b) => b,
    Err(_) => return Err("cannot read orders.json"),
  };
  let text = bytes.to_str();
  let doc = match text.parse_json() {
    Ok(j) => j,
    Err(e) => return Err("bad json: " + e),
  };
  let orders = match doc.as_list() {
    Some(l) => l,
    None => return Err("orders.json is not an array"),
  };

  let mut counts: Map<Str, Int> = Map::new();
  let mut totals: Map<Str, Int> = Map::new();
  let mut refund_n = 0;
  let mut refund_total = 0;
  let mut pend_n = 0;

  for o in orders {
    let status = o.get("status").and_then(|j| j.as_str()).unwrap_or("");
    if status == "paid" {
      let cust = o.get("customer").and_then(|j| j.as_str()).unwrap_or("");
      let total = order_total(o);
      let c = counts.get(cust).unwrap_or(0);
      counts.insert(cust, c + 1);
      let t = totals.get(cust).unwrap_or(0);
      totals.insert(cust, t + total);
    } else if status == "refunded" {
      refund_n = refund_n + 1;
      refund_total = refund_total + order_total(o);
    } else if status == "pending" {
      pend_n = pend_n + 1;
    }
  }

  let mut lines: List<Str> = [];
  for k in counts.keys() {
    let n = counts.get(k).unwrap_or(0);
    let t = totals.get(k).unwrap_or(0);
    lines.push(k + " " + n.to_str() + " " + t.to_str());
  }
  lines.push("refunded " + refund_n.to_str() + " " + refund_total.to_str());
  lines.push("pending " + pend_n.to_str());
  Ok(lines.join("\n"))
}

fn is_valid_domain(d: Str) -> Bool {
  if !d.contains(".") { return false; }
  if d.starts_with(".") || d.ends_with(".") { return false; }
  true
}

fn normalize(raw: Str) -> Option<Str> {
  let s = raw.trim().to_lowercase();
  if s.len() == 0 { return None; }

  let parts = s.split("@");
  if parts.len() != 2 { return None; }

  let local = parts[0];
  let domain = parts[1];
  if local.len() == 0 { return None; }
  if !is_valid_domain(domain) { return None; }

  let mut l = local;
  if domain == "gmail.com" {
    let plus = l.find("+");
    if let Some(i) = plus {
      l = l.slice(0, i);
    }
    l = l.replace(".", "");
  }

  Some(l + "@" + domain)
}

fn main(input: Dir) -> Result<Str, IoErr> {
  let text = input.read("emails.txt")?.to_str();

  let mut seen: Map<Str, Bool> = Map::new();
  let mut invalid = 0;

  for line in text.lines() {
    if line.trim().len() == 0 { continue; }
    match normalize(line) {
      Some(addr) => { seen.insert(addr, true); }
      None => { invalid = invalid + 1; }
    }
  }

  let mut out = "";
  for addr in seen.keys() {
    out = out + addr + "\n";
  }
  Ok(out + "invalid " + invalid.to_str())
}

fn all_digits(s: Str) -> Bool {
  let b = s.to_bytes();
  if b.len() == 0 { return false; }
  for i in 0..b.len() {
    if b[i] < 48 || b[i] > 57 { return false; }
  }
  true
}

fn numeral_value(c: Str) -> Int {
  match c {
    "I" => 1,
    "V" => 5,
    "X" => 10,
    "L" => 50,
    "C" => 100,
    "D" => 500,
    "M" => 1000,
    _ => 0,
  }
}

fn from_roman(s: Str) -> Int {
  let mut total = 0;
  let n = s.len();
  for i in 0..n {
    let v = numeral_value(s.slice(i, i + 1));
    if i + 1 < n && v < numeral_value(s.slice(i + 1, i + 2)) {
      total = total - v;
    } else {
      total = total + v;
    }
  }
  total
}

fn to_roman(v: Int) -> Str {
  let vals: List<Int> = [1000, 900, 500, 400, 100, 90, 50, 40, 10, 9, 5, 4, 1];
  let syms: List<Str> = ["M", "CM", "D", "CD", "C", "XC", "L", "XL", "X", "IX", "V", "IV", "I"];
  let mut out: Str = "";
  let mut n = v;
  for i in 0..13 {
    while n >= vals[i] {
      out = out + syms[i];
      n = n - vals[i];
    }
  }
  out
}

fn convert(s: Str) -> Str {
  if all_digits(s) {
    let n = s.parse_int().unwrap_or(0);
    if n >= 1 && n <= 3999 { return to_roman(n); }
    return "invalid";
  }
  let v = from_roman(s);
  if v >= 1 && v <= 3999 && to_roman(v) == s { return v.to_str(); }
  "invalid"
}

