fn check(line: Str) -> Str {
  let mut stack: List<Str> = [];
  let mut col = 0;
  for c in line.split("") {
    col = col + 1;
    if c == "(" || c == "[" || c == "{" {
      stack.push(c);
    } else if c == ")" || c == "]" || c == "}" {
      let want = if c == ")" { "(" } else if c == "]" { "[" } else { "{" };
      let closer = if c == ")" { ")" } else if c == "]" { "]" } else { "}" };
      if stack.len() == 0 {
        return "col " + col.to_str() + ": unexpected " + closer;
      }
      let top = stack[stack.len() - 1];
      let expected = if top == "(" { ")" } else if top == "[" { "]" } else { "}" };
      if top != want {
        return "col " + col.to_str() + ": expected " + expected + ", found " + closer;
      }
      stack.pop();
    }
  }
  if stack.len() == 0 {
    return "ok";
  }
  let top = stack[stack.len() - 1];
  let need = if top == "(" { ")" } else if top == "[" { "]" } else { "}" };
  "unclosed " + need
}

fn main(input: Dir) -> Result<Str, IoErr> {
  let lines = read_lines(input)?;
  let mut out: List<Str> = [];
  for line in lines {
    out.push(check(line));
  }
  Ok(out.join("\n"))
}

