fn sym(b: Int) -> Str {
  if b == 40 { "(" } else if b == 41 { ")" } else if b == 91 { "[" } else if b == 93 { "]" } else if b == 123 { "{" } else { "}" }
}

fn check(line: Str) -> Str {
  let mut stack: List<Int> = [];
  let chars = line.to_bytes();
  for i in 0..chars.len() {
    let b = chars[i];
    let col = i + 1;
    if b == 40 {
      stack.push(41);
    } else if b == 91 {
      stack.push(93);
    } else if b == 123 {
      stack.push(125);
    } else if b == 41 || b == 93 || b == 125 {
      if stack.len() == 0 {
        return "col " + col.to_str() + ": unexpected " + sym(b);
      }
      let need = stack[stack.len() - 1];
      if need != b {
        return "col " + col.to_str() + ": expected " + sym(need) + ", found " + sym(b);
      }
      stack.pop();
    }
  }
  if stack.len() == 0 {
    return "ok";
  }
  "unclosed " + sym(stack[stack.len() - 1])
}

fn main(input: Dir) -> Result<Str, IoErr> {
  let lines = read_lines(input)?;
  let mut out: List<Str> = [];
  for line in lines {
    out.push(check(line));
  }
  Ok(out.join("\n"))
}

fn pct(ts: List<Int>, p: Int) -> Int {
  let n = ts.len();
  ts[(p * n + 99) / 100 - 1]
}

fn main(input: Dir) -> Result<Str, IoErr> {
  let text = input.read("timings.log")?.to_str();
  let mut groups: Map<Str, List<Int>> = Map::new();
  for line in text.lines() {
    let parts = line.split(" ");
    if parts.len() != 3 { continue; }
    let Some(ms) = parts[2].parse_int() else { continue; };
    let key = parts[0] + " " + parts[1];
    let mut ts: List<Int> = [];
    if let Some(old) = groups.get(key) { ts = old; }
    ts.push(ms);
    groups.insert(key, ts);
  }
  let mut out: List<Str> = [];
  for key in groups.keys() {
    let mut ts: List<Int> = [];
    if let Some(old) = groups.get(key) { ts = old; }
    ts.sort();
    let n = ts.len();
    out.push(key + " count=" + n.to_str() + " p50=" + pct(ts, 50).to_str() + " p95=" + pct(ts, 95).to_str() + " max=" + ts[n - 1].to_str());
  }
  Ok(out.join("\n"))
}

struct Graph { w: Map<Str, Int>, nodes: Map<Str, Bool> }

struct Trip { src: Str, dst: Str }

fn words(line: Str) -> List<Str> {
  let spaced = line.replace("\t", " ");
  let mut out: List<Str> = [];
  for p in spaced.split(" ") {
    if p.len() > 0 { out.push(p); }
  }
  out
}

fn link(g: Graph, a: Str, b: Str, c: Int) -> Graph {
  let mut w = g.w;
  let mut nodes = g.nodes;
  let key = a + " " + b;
  nodes.insert(a, true);
  nodes.insert(b, true);
  match w.get(key) {
    Some(old) => { if c < old { w.insert(key, c); } }
    None => { w.insert(key, c); }
  }
  Graph { w: w, nodes: nodes }
}

// Distance from every town to `target`, by Dijkstra.
fn dist_to(g: Graph, target: Str) -> Map<Str, Int> {
  let names = g.nodes.keys();
  let mut dist: Map<Str, Int> = Map::new();
  let mut done: Map<Str, Bool> = Map::new();
  dist.insert(target, 0);
  loop {
    let mut best: Option<Str> = None;
    let mut best_d = 0;
    for n in names {
      if done.get(n).is_none() {
        if let Some(d) = dist.get(n) {
          if best.is_none() || d < best_d {
            best = Some(n);
            best_d = d;
          }
        }
      }
    }
    let Some(u) = best else { break; };
    done.insert(u, true);
    let du = dist.get(u).unwrap_or(0);
    for v in names {
      if done.get(v).is_none() {
        if let Some(c) = g.w.get(u + " " + v) {
          let nd = du + c;
          let better = match dist.get(v) {
            Some(old) => nd < old,
            None => true,
          };
          if better { dist.insert(v, nd); }
        }
      }
    }
  }
  dist
}

// Lexicographically smallest cheapest path, walking greedily from `src`.
fn cheapest_path(g: Graph, src: Str, dst: Str, dist: Map<Str, Int>) -> List<Str> {
  let names = g.nodes.keys();
  let mut path: List<Str> = [src];
  let mut cur = src;
  while cur != dst {
    let dc = dist.get(cur).unwrap_or(0);
    let mut nxt: Option<Str> = None;
    for v in names {
      if nxt.is_none() {
        if let Some(c) = g.w.get(cur + " " + v) {
          if let Some(dv) = dist.get(v) {
            if dv + c == dc { nxt = Some(v); }
          }
        }
      }
    }
    let Some(n) = nxt else { break; };
    path.push(n);
    cur = n;
  }
  path
}

fn main(input: Dir) -> Result<Str, IoErr> {
  let text = input.read("routes.txt")?.to_str();
  let mut g = Graph { w: Map::new(), nodes: Map::new() };
  let mut trips: List<Trip> = [];
  for raw in text.lines() {
    let line = raw.trim();
    if line.len() == 0 || line.starts_with("#") { continue; }
    let ws = words(line);
    if ws.len() == 4 && ws[0] == "road" {
      if let Some(c) = ws[3].parse_int() {
        if c > 0 {
          g = link(link(g, ws[1], ws[2], c), ws[2], ws[1], c);
        }
      }
    } else if ws.len() == 3 && ws[0] == "trip" {
      trips.push(Trip { src: ws[1], dst: ws[2] });
    }
  }

  let mut out: List<Str> = [];
  for t in trips {
    if t.src == t.dst {
      out.push(t.src + " 0");
    } else {
      let dist = dist_to(g, t.dst);
      if let Some(total) = dist.get(t.src) {
        let p = cheapest_path(g, t.src, t.dst, dist);
        out.push(p.join(" -> ") + " " + total.to_str());
      } else {
        out.push(t.src + " " + t.dst + " unreachable");
      }
    }
  }
  Ok(out.join("\n"))
}

struct Entry { path: Str, text: Str }

fn leaf(path: Str, value: Str) -> Entry {
  Entry { path: path, text: path + "=" + value }
}

fn child_path(path: Str, top: Bool, key: Str) -> Str {
  if top { key } else { path + "." + key }
}

fn merge_map(target: Map<Str, Json>, patch: Map<Str, Json>) -> Map<Str, Json> {
  let mut out = target;
  for k in patch.keys() {
    let Some(v) = patch.get(k) else { continue; };
    match v {
      Json::Null => { out.remove(k); }
      Json::Obj(pm) => {
        let merged = match out.get(k) {
          Some(Json::Obj(tm)) => merge_map(tm, pm),
          _ => merge_map(Map::new(), pm),
        };
        out.insert(k, Json::Obj(merged));
      }
      _ => { out.insert(k, v); }
    }
  }
  out
}

fn flatten(path: Str, top: Bool, v: Json, acc: List<Entry>) -> List<Entry> {
  let mut out = acc;
  match v {
    Json::Obj(m) => {
      if m.len() == 0 { out.push(leaf(path, "{}")); }
      for k in m.keys() {
        let Some(child) = m.get(k) else { continue; };
        out = flatten(child_path(path, top, k), false, child, out);
      }
    }
    Json::Arr(xs) => {
      if xs.len() == 0 { out.push(leaf(path, "[]")); }
      for i in 0..xs.len() {
        out = flatten(child_path(path, top, i.to_str()), false, xs[i], out);
      }
    }
    _ => { out.push(leaf(path, v.to_json())); }
  }
  out
}

fn main(input: Dir) -> Result<Str, Str> {
  let base_text = input.read("base.json").map_err(|e| "cannot read base.json")?.to_str();
  let over_text = input.read("override.json").map_err(|e| "cannot read override.json")?.to_str();
  let base = base_text.parse_json().map_err(|e| "base.json: " + e)?;
  let over = over_text.parse_json().map_err(|e| "override.json: " + e)?;
  let base_map = base.as_map().ok_or("base.json is not an object")?;
  let over_map = over.as_map().ok_or("override.json is not an object")?;
  let merged = merge_map(base_map, over_map);
  let entries = flatten("", true, Json::Obj(merged), []);
  let mut sorted = entries;
  sorted.sort_by_key(|e| e.path);
  let lines = sorted.map(|e| e.text);
  Ok(lines.join("\n"))
}

fn main(input: Dir, out: Dir) -> Result<Str, IoErr> {
  let text = input.read("app.log")?.to_str();

  let mut error_log = "";
  let mut warn_log = "";
  let mut info_log = "";

  let mut error_n = 0;
  let mut warn_n = 0;
  let mut info_n = 0;
  let mut other_n = 0;

  for line in text.lines() {
    if line.trim().len() == 0 {
      continue;
    }

    let parts = line.split(" ");
    if parts.len() < 3 {
      other_n += 1;
      continue;
    }

    let level = parts[1].to_uppercase();
    if level == "ERROR" {
      error_log = error_log + line + "\n";
      error_n += 1;
    } else if level == "WARN" || level == "WARNING" {
      warn_log = warn_log + line + "\n";
      warn_n += 1;
    } else if level == "INFO" {
      info_log = info_log + line + "\n";
      info_n += 1;
    } else {
      other_n += 1;
    }
  }

  out.write("error.log", error_log.to_bytes())?;
  out.write("warn.log", warn_log.to_bytes())?;
  out.write("info.log", info_log.to_bytes())?;

  Ok("error " + error_n.to_str() + "\nwarn " + warn_n.to_str() + "\ninfo " + info_n.to_str() + "\nother " + other_n.to_str())
}

fn walk(input: Dir, prefix: Str) -> Result<List<Str>, IoErr> {
  let mut key: Str = prefix;
  if key.len() > 0 {
    key = key.slice(0, key.len() - 1);
  }
  let names = input.list(key)?;
  let mut files: List<Str> = [];
  for name in names {
    if name.ends_with("/") {
      let sub = walk(input, prefix + name)?;
      for f in sub {
        files.push(f);
      }
    } else {
      files.push(prefix + name);
    }
  }
  Ok(files)
}

fn main(input: Dir, out: Dir) -> Result<Str, IoErr> {
  let mut paths = walk(input, "")?;
  paths.sort();
  let mut csv: Str = "path,bytes,lines\n";
  let mut total = 0;
  let mut n = 0;
  for p in paths {
    let b = input.read(p)?;
    let size = b.len();
    let mut nl = 0;
    for i in 0..size {
      if b[i] == 10 {
        nl += 1;
      }
    }
    let mut lines = nl;
    if size > 0 {
      if b[size - 1] != 10 {
        lines += 1;
      }
    }
    csv = csv + p + "," + size.to_str() + "," + lines.to_str() + "\n";
    total += size;
    n += 1;
  }
  out.write("index.csv", csv.to_bytes())?;
  Ok("files " + n.to_str() + " bytes " + total.to_str())
}

fn split_csv(line: Str) -> List<Str> {
  let b = line.to_bytes();
  let n = b.len();
  let mut out: List<Str> = [];
  let mut cur = "".to_bytes();
  let mut inq = false;
  let mut i = 0;
  while i < n {
    let c = b[i];
    if inq {
      if c == 34 {
        if i + 1 < n && b[i + 1] == 34 {
          cur.push(34);
          i = i + 2;
          continue;
        }
        inq = false;
      } else {
        cur.push(c);
      }
    } else {
      if c == 34 {
        inq = true;
      } else if c == 44 {
        out.push(cur.to_str());
        cur = "".to_bytes();
      } else {
        cur.push(c);
      }
    }
    i = i + 1;
  }
  out.push(cur.to_str());
  out
}

fn row_json(f: List<Str>) -> Option<Json> {
  let id = f[0].trim().parse_int()?;
  let v = f[3].trim().to_lowercase();
  let active = v == "yes" || v == "true" || v == "1";
  let mut tags: List<Json> = [];
  let tag_field = f[4];
  for t in tag_field.split(";") {
    let s = t.trim();
    if s != "" {
      tags.push(Json::Str(s));
    }
  }
  let mut m: Map<Str, Json> = Map::new();
  m.insert("id", Json::Num(id));
  m.insert("name", Json::Str(f[1]));
  m.insert("email", Json::Str(f[2]));
  m.insert("active", Json::Bool(active));
  m.insert("tags", Json::Arr(tags));
  Some(Json::Obj(m))
}

fn main(input: Dir, out: Dir) -> Result<Str, IoErr> {
  let text = input.read("users.csv")?.to_str();
  let mut rows: List<Json> = [];
  let mut skipped = 0;
  let mut seen_header = false;
  for line in text.lines() {
    if line.trim() == "" {
      continue;
    }
    if !seen_header {
      seen_header = true;
      continue;
    }
    let fields = split_csv(line);
    if fields.len() != 5 {
      skipped = skipped + 1;
      continue;
    }
    let Some(row) = row_json(fields) else {
      skipped = skipped + 1;
      continue;
    };
    rows.push(row);
  }
  let n = rows.len();
  out.write("users.json", Json::Arr(rows).to_json().to_bytes())?;
  Ok("rows " + n.to_str() + " skipped " + skipped.to_str())
}

fn normalize(name: Str) -> Str {
  let mut out = "";
  let mut pending_dash = false;
  let lower = name.to_lowercase();
  for i in 0..lower.len() {
    let c = lower.slice(i, i + 1);
    let keep = (c >= "a" && c <= "z") || (c >= "0" && c <= "9") || c == ".";
    if keep {
      if pending_dash && out.len() > 0 {
        out = out + "-";
      }
      pending_dash = false;
      out = out + c;
    } else {
      pending_dash = true;
    }
  }
  out
}

fn main(input: Dir, out: Dir) -> Result<Str, IoErr> {
  let names = input.list("")?;
  let mut report = "";
  let mut taken: Map<Str, Bool> = Map::new();
  for name in names {
    let data = input.read(name)?;
    let new_name = normalize(name);
    if taken.get(new_name).is_some() {
      report = report + name + " skipped\n";
    } else {
      taken.insert(new_name, true);
      out.create(new_name, data)?;
      report = report + name + " -> " + new_name + "\n";
    }
  }
  Ok(report)
}

fn is_part_name(name: Str) -> bool {
  let Some(rest) = name.strip_prefix("part-") else { return false; };
  let Some(digits) = rest.strip_suffix(".txt") else { return false; };
  if digits.len() == 0 { return false; }
  let b = digits.to_bytes();
  let mut i = 0;
  while i < b.len() {
    if b[i] < 48 || b[i] > 57 { return false; }
    i += 1;
  }
  true
}

fn parse_part(data: Bytes) -> Option<List<Int>> {
  let mut i = 0;
  while i < data.len() {
    if data[i] >= 128 { return None; }
    i += 1;
  }
  let text = data.to_str();
  let mut vals: List<Int> = [];
  for line in text.lines() {
    let t = line.trim();
    if t.len() == 0 { continue; }
    let Some(v) = t.parse_int() else { return None; };
    vals.push(v);
  }
  Some(vals)
}

fn main(input: Dir, out: Dir) -> Result<Str, IoErr> {
  let names = input.list("")?;
  let mut parts: Int = 0;
  let mut corrupt: Int = 0;
  let mut all: List<Int> = [];
  for name in names {
    if !is_part_name(name) { continue; }
    parts += 1;
    let Ok(data) = input.read(name) else {
      corrupt += 1;
      continue;
    };
    let Some(vals) = parse_part(data) else {
      corrupt += 1;
      continue;
    };
    for v in vals { all.push(v); }
  }
  all.sort();
  let mut buf = "".to_bytes();
  let mut values: Int = 0;
  let mut last: Option<Int> = None;
  for v in all {
    if last == Some(v) { continue; }
    last = Some(v);
    buf.extend(v.to_str().to_bytes());
    buf.extend("\n".to_bytes());
    values += 1;
  }
  out.write("merged.txt", buf)?;
  Ok("parts " + parts.to_str() + " corrupt " + corrupt.to_str() + " values " + values.to_str())
}

