struct Pending { name: Str, status: Str }

fn plan(src: Dir, dst: Dir, names: List<Str>) -> Result<List<Str>, IoErr> {
  let mut out: List<Str> = [];
  for name in names {
    let a = src.read(name)?;
    let same_bytes = match dst.exists(name)? {
      true => dst.read(name)?.ct_eq(a),
      false => false,
    };
    if same_bytes {
      out.push("same " + name);
    } else if dst.exists(name)? {
      out.push("updated " + name);
    } else {
      out.push("added " + name);
    }
  }
  Ok(out)
}

fn copy_all(src: Dir, dst: Dir, names: List<Str>) -> Result<(), IoErr> {
  for name in names {
    let a = src.read(name)?;
    let b = dst.exists(name)?;
    if b {
      let cur = dst.read(name)?;
      if !cur.ct_eq(a) {
        dst.write(name, a)?;
      }
    } else {
      dst.create(name, a)?;
    }
  }
  Ok(())
}

fn main(src: Dir, dst: Dir) -> Result<Str, IoErr> {
  let mut names = src.list("")?;
  names.sort();
  let mut dst_names = dst.list("")?;
  let mut kept = 0;
  for d in dst_names {
    if !names.contains(d) {
      kept = kept + 1;
    }
  }
  let lines = plan(src, dst, names)?;
  copy_all(src, dst, names)?;
  let mut out = "";
  for l in lines {
    out = out + l + "\n";
  }
  Ok(out + "kept " + kept.to_str())
}

struct Row { page: Str, total: Int }

fn read_visits(input: Dir) -> Result<Map<Str, Int>, IoErr> {
  let text = input.read("visits.txt")?.to_str();
  let mut seen: Map<Str, Int> = Map::new();
  for line in text.lines() {
    let page = line.trim();
    if page.len() == 0 { continue; }
    let n = match seen.get(page) { Some(c) => c + 1, None => 1 };
    seen.insert(page, n);
  }
  Ok(seen)
}

fn record(counts: Kv, seen: Map<Str, Int>) -> Result<(), KvErr> {
  for page in seen.keys() {
    let n = match seen.get(page) { Some(c) => c, None => 0 };
    counts.add("visits:" + page, n)?;
  }
  Ok(())
}

fn report(counts: Kv) -> Result<List<Row>, KvErr> {
  let mut rows: List<Row> = [];
  let keys = counts.keys("visits:")?;
  for key in keys {
    let total = match counts.get(key)? {
      Some(b) => b.to_str().parse_int().unwrap_or(0),
      None => 0,
    };
    rows.push(Row { page: key.slice(7, key.len()), total: total });
  }
  rows.sort_by(|a: Row, b: Row| a.total > b.total || (a.total == b.total && a.page < b.page));
  Ok(rows)
}

fn render(rows: List<Row>) -> Str {
  let mut lines: List<Str> = [];
  for r in rows { lines.push(r.page + " " + r.total.to_str()); }
  lines.join("\n")
}

fn main(input: Dir, counts: Kv) -> Result<Str, Str> {
  let Ok(seen) = read_visits(input) else { return Err("cannot read visits.txt"); };
  let Ok(_) = record(counts, seen) else { return Err("cannot update counts"); };
  let Ok(rows) = report(counts) else { return Err("cannot read counts"); };
  Ok(render(rows))
}

const PREFIX: Str = "u:";

fn key(id: Str) -> Str {
  PREFIX + id
}

fn encode(name: Str, email: Str) -> Str {
  name + " " + email
}

fn name_of(v: Str) -> Str {
  let parts = v.split(" ");
  parts[0]
}

fn email_of(v: Str) -> Str {
  let parts = v.split(" ");
  parts[1]
}

fn json_user(id: Str, v: Str) -> Str {
  let name = name_of(v);
  let email = email_of(v);
  "{\"id\":" + Json::Str(id).to_json() + ",\"name\":" + Json::Str(name).to_json() + ",\"email\":" + Json::Str(email).to_json() + "}"
}

fn get_user(users: Kv, id: Str) -> Result<Option<Str>, Str> {
  match users.get(key(id)) {
    Ok(Some(b)) => Ok(Some(b.to_str())),
    Ok(None) => Ok(None),
    Err(_) => Err("kv get failed"),
  }
}

fn store(users: Kv, id: Str, name: Str, email: Str) -> Result<(), Str> {
  match users.set(key(id), encode(name, email).to_bytes()) {
    Ok(_) => Ok(()),
    Err(_) => Err("kv set failed"),
  }
}

fn delete_user(users: Kv, id: Str) -> Result<(), Str> {
  match users.delete(key(id)) {
    Ok(_) => Ok(()),
    Err(_) => Err("kv delete failed"),
  }
}

fn list_keys(users: Kv) -> Result<List<Str>, Str> {
  match users.keys(PREFIX) {
    Ok(ks) => Ok(ks),
    Err(_) => Err("kv keys failed"),
  }
}

fn handle(users: Kv, t: Str) -> Result<Str, Str> {
  let w = t.split(" ");
  let n = w.len();
  let cmd = w[0];

  if cmd == "put" && n == 4 {
    store(users, w[1], w[2], w[3])?;
    return Ok("ok " + w[1]);
  }

  if cmd == "rename" && n == 3 {
    let out = match get_user(users, w[1])? {
      Some(v) => { store(users, w[1], w[2], email_of(v))?; "ok " + w[1] }
      None => "missing " + w[1],
    };
    return Ok(out);
  }

  if cmd == "get" && n == 2 {
    let out = match get_user(users, w[1])? {
      Some(v) => json_user(w[1], v),
      None => "missing " + w[1],
    };
    return Ok(out);
  }

  if cmd == "del" && n == 2 {
    let out = match get_user(users, w[1])? {
      Some(_) => { delete_user(users, w[1])?; "ok " + w[1] }
      None => "missing " + w[1],
    };
    return Ok(out);
  }

  if cmd == "count" && n == 1 {
    let ks = list_keys(users)?;
    let total = ks.len();
    return Ok("count " + total.to_str());
  }

  Ok("bad " + t)
}

fn main(input: Dir, users: Kv) -> Result<Str, Str> {
  let text = match input.read("commands.txt") {
    Ok(b) => b.to_str(),
    Err(_) => return Err("cannot read commands.txt"),
  };

  let mut out: List<Str> = [];
  for line in text.lines() {
    let t = line.trim();
    if t == "" {
      continue;
    }
    out.push(handle(users, t)?);
  }
  Ok(out.join("\n"))
}

struct Event { id: Str, account: Str, cents: Int }

fn parse_event(line: Str) -> Option<Event> {
  let j = line.parse_json().ok()?;
  let id = j.get("id")?.as_str()?;
  let account = j.get("account")?.as_str()?;
  let cents = j.get("cents")?.as_int()?;
  Some(Event { id: id, account: account, cents: cents })
}

fn main(input: Dir, state: Kv) -> Result<Str, Str> {
  let bytes = input.read("events.jsonl").map_err(|e| "cannot read events.jsonl")?;
  let text = bytes.to_str();

  let mut applied = 0;
  let mut duplicate = 0;
  let mut rejected = 0;

  for line in text.lines() {
    let raw = line.trim();
    if raw == "" { continue; }
    let ev = match parse_event(raw) {
      Some(e) => e,
      None => { rejected += 1; continue; }
    };
    let key = "seen:" + ev.id.sha256().to_hex();
    let fresh = state.swap(key, None, Some("1".to_bytes())).map_err(|e| "state failed")?;
    if !fresh {
      duplicate += 1;
      continue;
    }
    state.add("bal:" + ev.account, ev.cents).map_err(|e| "state failed")?;
    applied += 1;
  }

  let mut out = "applied " + applied.to_str() + " duplicate " + duplicate.to_str() + " rejected " + rejected.to_str();

  let keys = state.keys("bal:").map_err(|e| "state failed")?;
  for k in keys {
    let Some(name) = k.strip_prefix("bal:") else { continue; };
    let cents = state.get(k).map_err(|e| "state failed")?
      .and_then(|b| b.to_str().parse_int())
      .unwrap_or(0);
    out = out + "\n" + name + " " + cents.to_str();
  }

  Ok(out)
}

fn count_of(limits: Kv, key: Str) -> Result<Int, Str> {
  let v = limits.get(key).map_err(|e| "kv get failed")?;
  match v {
    Some(b) => Ok(b.to_str().parse_int().unwrap_or(0)),
    None => Ok(0),
  }
}

fn bump(limits: Kv, key: Str, n: Int) -> Result<(), Str> {
  limits.set(key, n.to_str().to_bytes()).map_err(|e| "kv set failed")
}

fn main(input: Dir, limits: Kv) -> Result<Str, Str> {
  let text = input.read("requests.txt").map_err(|e| "cannot read requests.txt")?.to_str();
  let mut out: List<Str> = [];
  for line in text.lines() {
    let parts = line.trim().split(" ");
    if parts.len() != 2 { continue; }
    let Some(t) = parts[0].parse_int() else { continue; };
    let client = parts[1];
    let key = (t / 60).to_str() + ":" + client;
    let n = count_of(limits, key)?;
    if n < 3 {
      bump(limits, key, n + 1)?;
      out.push(parts[0] + " " + client + " allow");
    } else {
      out.push(parts[0] + " " + client + " deny");
    }
  }
  Ok(out.join("\n"))
}

// Season leaderboard: totals live in the Kv store and accumulate over runs.
// Each run applies games.txt, then prints the top 3 players.

fn kv_fail(e: KvErr) -> Str {
  "board store failed"
}

fn io_fail(e: IoErr) -> Str {
  "cannot read games.txt"
}

// Adds `pts` points and one game played for `name`.
// `add` with 0 still creates the key, so a loser with no points is recorded.
fn add_pts(board: Kv, name: Str, pts: Int) -> Result<(), Str> {
  board.add("pts:" + name, pts).map_err(kv_fail)?;
  board.add("pl:" + name, 1).map_err(kv_fail)?;
  Ok(())
}

fn read_int(board: Kv, key: Str) -> Result<Int, Str> {
  let v = board.get(key).map_err(kv_fail)?;
  match v {
    Some(b) => Ok(b.to_str().parse_int().unwrap_or(0)),
    None => Ok(0),
  }
}

struct Row {
  name: Str,
  pts: Int,
  played: Int,
}

fn standings(board: Kv) -> Result<List<Row>, Str> {
  let keys = board.keys("pts:").map_err(kv_fail)?;
  let mut rows: List<Row> = [];
  for k in keys {
    let name = k.strip_prefix("pts:").unwrap_or("");
    let pts = read_int(board, "pts:" + name)?;
    let played = read_int(board, "pl:" + name)?;
    rows.push(Row { name: name, pts: pts, played: played });
  }
  Ok(rows)
}

// True when `a` ranks before `b`: more points, then fewer games, then name.
fn ahead(a: Row, b: Row) -> Bool {
  if a.pts != b.pts {
    return a.pts > b.pts;
  }
  if a.played != b.played {
    return a.played < b.played;
  }
  a.name < b.name
}

fn main(input: Dir, board: Kv) -> Result<Str, Str> {
  let bytes = input.read("games.txt").map_err(io_fail)?;
  let text = bytes.to_str();

  for line in text.lines() {
    let parts = line.trim().split(" ");
    if parts.len() == 2 && parts[0].len() > 0 && parts[1].len() > 0 {
      add_pts(board, parts[0], 3)?;
      add_pts(board, parts[1], 0)?;
    } else if parts.len() == 3 && parts[2] == "draw" && parts[0].len() > 0 && parts[1].len() > 0 {
      add_pts(board, parts[0], 1)?;
      add_pts(board, parts[1], 1)?;
    }
  }

  let mut rows = standings(board)?;
  rows.sort_by(ahead);

  let n = rows.len().min(3);
  let mut out: List<Str> = [];
  for i in 0..n {
    let r = rows[i];
    out.push((i + 1).to_str() + ". " + r.name + " " + r.pts.to_str() + " " + r.played.to_str());
  }
  Ok(out.join("\n"))
}

struct Order { order_id: Int, customer: Str, product: Str, qty: Int, unit_cents: Int }

fn parse_order(line: Str) -> Option<Order> {
  let f = line.split(",");
  if f.len() != 5 { return None; }
  let order_id = f[0].parse_int()?;
  let qty = f[3].parse_int()?;
  let unit_cents = f[4].parse_int()?;
  Some(Order { order_id: order_id, customer: f[1], product: f[2], qty: qty, unit_cents: unit_cents })
}

fn text_at(row: List<SqlValue>, i: Int) -> Result<Str, DbErr> {
  match row[i] {
    SqlValue::Text(s) => Ok(s),
    _ => Err(DbErr::Invalid("unexpected column type")),
  }
}

fn int_at(row: List<SqlValue>, i: Int) -> Result<Int, DbErr> {
  match row[i] {
    SqlValue::Int(n) => Ok(n),
    _ => Err(DbErr::Invalid("unexpected column type")),
  }
}

fn import(shop: Db, text: Str) -> Result<Str, DbErr> {
  let no_params: List<SqlValue> = [];
  shop.exec("CREATE TABLE IF NOT EXISTS orders (order_id INTEGER PRIMARY KEY, customer TEXT NOT NULL, product TEXT NOT NULL, qty INTEGER NOT NULL, unit_cents INTEGER NOT NULL)", no_params)?;
  let mut imported = 0;
  let mut skipped = 0;
  let mut rejected = 0;
  let mut first = true;
  for line in text.lines() {
    if first { first = false; continue; }
    if line.trim().len() == 0 { continue; }
    let Some(o) = parse_order(line) else { rejected += 1; continue; };
    let changed = shop.exec(
      "INSERT OR IGNORE INTO orders (order_id, customer, product, qty, unit_cents) VALUES (?, ?, ?, ?, ?)",
      [SqlValue::Int(o.order_id), SqlValue::Text(o.customer), SqlValue::Text(o.product), SqlValue::Int(o.qty), SqlValue::Int(o.unit_cents)]
    )?;
    if changed == 1 { imported += 1; } else { skipped += 1; }
  }
  let top = shop.query("SELECT product, SUM(qty * unit_cents) AS revenue, COUNT(*) AS n FROM orders GROUP BY product ORDER BY revenue DESC, product ASC LIMIT 3", no_params)?;
  let mut out = "imported " + imported.to_str() + " skipped " + skipped.to_str() + " rejected " + rejected.to_str();
  for row in top {
    let product = text_at(row, 0)?;
    let revenue = int_at(row, 1)?;
    let n = int_at(row, 2)?;
    out = out + "\n" + product + " " + revenue.to_str() + " " + n.to_str();
  }
  Ok(out)
}

fn main(input: Dir, shop: Db) -> Result<Str, DbErr> {
  let bytes = match input.read("orders.csv") {
    Ok(b) => b,
    Err(_) => return Err(DbErr::Invalid("cannot read orders.csv")),
  };
  import(shop, bytes.to_str())
}

struct Cust { id: Int, name: Str, country: Str, orders: Int, revenue: Int }

struct Country {
  name: Str,
  customers: Int,
  orders: Int,
  revenue: Int,
  top: Str,
  top_rev: Int,
  top_id: Int,
}

fn as_int(v: SqlValue) -> Option<Int> {
  match v {
    SqlValue::Int(n) => Some(n),
    _ => None,
  }
}

fn as_text(v: SqlValue) -> Option<Str> {
  match v {
    SqlValue::Text(s) => Some(s),
    _ => None,
  }
}

fn decode(row: List<SqlValue>) -> Option<Cust> {
  if row.len() != 5 { return None; }
  Some(Cust {
    id: as_int(row[0])?,
    name: as_text(row[1])?,
    country: as_text(row[2])?,
    orders: as_int(row[3])?,
    revenue: as_int(row[4])?,
  })
}

fn main(shop: Db) -> Result<Str, DbErr> {
  let rows = shop.query(
    "SELECT c.id, c.name, c.country, COUNT(o.id), SUM(o.total_cents) "
      + "FROM customers c JOIN orders o ON o.customer_id = c.id "
      + "WHERE o.status = 'paid' AND o.placed >= '2026-01-01' AND o.placed < '2027-01-01' "
      + "GROUP BY c.id, c.name, c.country ORDER BY c.id",
    []
  )?;

  let mut by: Map<Str, Country> = Map::new();
  for row in rows {
    let Some(c) = decode(row) else { continue; };
    let cur = by.get(c.country).unwrap_or(Country {
      name: c.country,
      customers: 0,
      orders: 0,
      revenue: 0,
      top: "",
      top_rev: 0,
      top_id: 0,
    });
    let better = cur.customers == 0
      || c.revenue > cur.top_rev
      || (c.revenue == cur.top_rev && c.id < cur.top_id);
    let mut top = cur.top;
    let mut top_rev = cur.top_rev;
    let mut top_id = cur.top_id;
    if better {
      top = c.name;
      top_rev = c.revenue;
      top_id = c.id;
    }
    by.insert(c.country, Country {
      name: c.country,
      customers: cur.customers + 1,
      orders: cur.orders + c.orders,
      revenue: cur.revenue + c.revenue,
      top: top,
      top_rev: top_rev,
      top_id: top_id,
    });
  }

  let mut list: List<Country> = [];
  for k in by.keys() {
    let Some(x) = by.get(k) else { continue; };
    list.push(x);
  }
  list.sort_by(|a, b| a.revenue > b.revenue || (a.revenue == b.revenue && a.name < b.name));

  let mut out: Str = "";
  let mut total_orders = 0;
  let mut total_rev = 0;
  for x in list {
    out = out + x.name + " customers=" + x.customers.to_str()
      + " orders=" + x.orders.to_str()
      + " revenue=" + x.revenue.to_str()
      + " top=" + x.top + "\n";
    total_orders += x.orders;
    total_rev += x.revenue;
  }
  out = out + "total orders=" + total_orders.to_str() + " revenue=" + total_rev.to_str() + "\n";
  Ok(out)
}

struct Batch { name: Str, moves: List<Str> }
struct Move { sku: Str, delta: Int }

fn io_msg(e: IoErr) -> Str {
  match e {
    IoErr::NotFound => "moves.txt not found",
    IoErr::Denied => "input denied",
    IoErr::TooLarge => "moves.txt too large",
    IoErr::InvalidPath => "invalid path",
    IoErr::Exists => "exists",
  }
}

fn db_msg(e: DbErr) -> Str {
  match e {
    DbErr::Invalid(m) => m,
    DbErr::Denied => "database denied",
    DbErr::Busy => "database busy",
    DbErr::TooLarge => "database result too large",
    DbErr::Constraint(m) => m,
  }
}

fn sku_of(row: List<SqlValue>) -> Str {
  let v = row[0];
  match v {
    SqlValue::Text(s) => s,
    _ => "",
  }
}

fn qty_of(row: List<SqlValue>) -> Int {
  let v = row[1];
  match v {
    SqlValue::Int(q) => q,
    _ => 0,
  }
}

// Groups lines into batches. Move lines before the first header are ignored.
fn parse_batches(text: Str) -> List<Batch> {
  let mut out: List<Batch> = [];
  let mut in_batch = false;
  let mut name = "";
  let mut moves: List<Str> = [];
  for raw in text.lines() {
    let line = raw.trim();
    if line.len() == 0 {
      continue;
    }
    if line.starts_with("batch ") {
      if in_batch {
        out.push(Batch { name: name, moves: moves });
      }
      in_batch = true;
      name = line.slice(6, line.len()).trim();
      moves = [];
    } else if in_batch {
      moves.push(line);
    }
  }
  if in_batch {
    out.push(Batch { name: name, moves: moves });
  }
  out
}

fn positive(d: Str) -> Option<Int> {
  if d.len() == 0 || d.starts_with("+") || d.starts_with("-") {
    return None;
  }
  let n = d.parse_int()?;
  if n > 0 { Some(n) } else { None }
}

fn parse_move(line: Str) -> Option<Move> {
  let parts = line.split(" ");
  if parts.len() != 2 || parts[0].len() == 0 {
    return None;
  }
  let sku = parts[0];
  let amt = parts[1];
  if let Some(d) = amt.strip_prefix("+") {
    let n = positive(d)?;
    return Some(Move { sku: sku, delta: n });
  }
  if let Some(d) = amt.strip_prefix("-") {
    let n = positive(d)?;
    return Some(Move { sku: sku, delta: 0 - n });
  }
  None
}

fn db_qty(stock: Db, sku: Str) -> Result<Int, Str> {
  let rows = stock
    .query("SELECT qty FROM stock WHERE sku = ?", [SqlValue::Text(sku)])
    .map_err(db_msg)?;
  if rows.len() == 0 {
    return Ok(0);
  }
  let row = rows[0];
  Ok(qty_of(row))
}

// Returns "skipped", "rejected" or "applied". Nothing is written unless "applied".
fn run_batch(stock: Db, b: Batch) -> Result<Str, Str> {
  let seen = stock
    .query("SELECT 1 FROM applied WHERE name = ?", [SqlValue::Text(b.name)])
    .map_err(db_msg)?;
  if seen.len() > 0 {
    return Ok("skipped");
  }

  // Simulate the moves in order, so an intermediate dip below zero rejects too.
  let mut work: Map<Str, Int> = Map::new();
  let mut ok = true;
  for line in b.moves {
    let Some(m) = parse_move(line) else {
      ok = false;
      break;
    };
    let cur = match work.get(m.sku) {
      Some(q) => q,
      None => db_qty(stock, m.sku)?,
    };
    let next = cur + m.delta;
    if next < 0 {
      ok = false;
      break;
    }
    work.insert(m.sku, next);
  }
  if !ok {
    return Ok("rejected");
  }

  // Write final quantities and the batch name in one transaction.
  let mut stmts: List<Str> = [];
  let mut params: List<List<SqlValue>> = [];
  for sku in work.keys() {
    let q = work.get(sku).unwrap_or(0);
    stmts.push("INSERT OR REPLACE INTO stock (sku, qty) VALUES (?, ?)");
    params.push([SqlValue::Text(sku), SqlValue::Int(q)]);
  }
  stmts.push("INSERT INTO applied (name) VALUES (?)");
  params.push([SqlValue::Text(b.name)]);
  stock.transaction(stmts, params).map_err(db_msg)?;
  Ok("applied")
}

fn main(input: Dir, stock: Db) -> Result<Str, Str> {
  stock.exec("CREATE TABLE IF NOT EXISTS stock (sku TEXT PRIMARY KEY, qty INTEGER NOT NULL)", []).map_err(db_msg)?;
  stock.exec("CREATE TABLE IF NOT EXISTS applied (name TEXT PRIMARY KEY)", []).map_err(db_msg)?;

  let text = input.read("moves.txt").map_err(io_msg)?.to_str();

  let mut lines: List<Str> = [];
  for b in parse_batches(text) {
    let status = run_batch(stock, b)?;
    lines.push(b.name + " " + status);
  }

  let rows = stock
    .query("SELECT sku, qty FROM stock WHERE qty != 0 ORDER BY sku", [])
    .map_err(db_msg)?;
  for row in rows {
    lines.push(sku_of(row) + " " + qty_of(row).to_str());
  }

  Ok(lines.join("\n"))
}

