}

fn as_count(v: SqlValue) -> Int {
  match v {
    SqlValue::Int(n) => n,
    _ => 0,
  }
}

fn find(crm: Db, email: Str) -> Result<Option<Contact>, Str> {
  let rows = crm.query("SELECT name, phone FROM contacts WHERE email = ?", [SqlValue::Text(email)]).map_err(db_msg)?;
  if rows.len() == 0 { return Ok(None); }
  let row = rows[0];
  Ok(Some(Contact { name: as_text(row[0]), phone: as_text(row[1]) }))
}

fn insert_row(crm: Db, email: Str, name: Str, phone: Str) -> Result<(), Str> {
  crm.exec("INSERT INTO contacts (email, name, phone) VALUES (?, ?, ?)", [SqlValue::Text(email), SqlValue::Text(name), SqlValue::Text(phone)]).map_err(db_msg)?;
  Ok(())
}

fn update_row(crm: Db, email: Str, name: Str, phone: Str) -> Result<(), Str> {
  crm.exec("UPDATE contacts SET name = ?, phone = ? WHERE email = ?", [SqlValue::Text(name), SqlValue::Text(phone), SqlValue::Text(email)]).map_err(db_msg)?;
  Ok(())
}

fn main(input: Dir, crm: Db) -> Result<Str, Str> {
  crm.exec("CREATE TABLE IF NOT EXISTS contacts (email TEXT PRIMARY KEY, name TEXT NOT NULL, phone TEXT NOT NULL)", []).map_err(db_msg)?;

  let bytes = input.read("contacts.csv").map_err(io_msg)?;
  let text = bytes.to_str();

  let mut seen_header = false;
  let mut inserted = 0;
  let mut updated = 0;
  let mut unchanged = 0;
  let mut rejected = 0;

  for raw in text.lines() {
    let line = raw.trim();
    if line == "" { continue; }
    if !seen_header { seen_header = true; continue; }

    let parts = line.split(",");
    if parts.len() != 3 { rejected += 1; continue; }

    let email = parts[0].trim().to_lowercase();
    if !email.contains("@") { rejected += 1; continue; }

    let name = parts[1].trim();
    let phone = parts[2].trim();

    let found = find(crm, email)?;
    match found {
      None => {
        insert_row(crm, email, name, phone)?;
        inserted += 1;
      }
      Some(c) => {
        if c.name != name || c.phone != phone {
          update_row(crm, email, name, phone)?;
          updated += 1;
        } else {
          unchanged += 1;
        }
      }
    }
  }

  let counted = crm.query("SELECT COUNT(*) FROM contacts", []).map_err(db_msg)?;
  let count_row = counted[0];
  let total = as_count(count_row[0]);

  let missing = crm.query("SELECT email FROM contacts WHERE phone = '' ORDER BY email", []).map_err(db_msg)?;

  let mut out = "inserted " + inserted.to_str() + " updated " + updated.to_str() + " unchanged " + unchanged.to_str() + " rejected " + rejected.to_str();
  out = out + "\ncontacts " + total.to_str();
  for row in missing {
    out = out + "\nmissing phone: " + as_text(row[0]);
  }
  Ok(out)
}

struct Entry { name: Str, count: Int }

fn valid_name(name: Str) -> Bool {
  if name.len() < 1 || name.len() > 32 { return false; }
  for b in name.to_bytes() {
    let ok = (b >= 97 && b <= 122) || (b >= 48 && b <= 57) || b == 45;
    if !ok { return false; }
  }
  true
}

fn json_entry(name: Str, count: Int) -> Str {
  "{\"name\": \"" + name + "\", \"count\": " + count.to_str() + "}"
}

fn read_count(counts: Kv, name: Str) -> Result<Int, KvErr> {
  match counts.get(name)? {
    Some(b) => Ok(b.to_str().parse_int().unwrap_or(0)),
    None => Ok(0),
  }
}

fn reply(res: Outgoing, status: Int, body: Str) -> Result<(), WebErr> {
  res.send(status, ["content-type"], ["application/json"], body.to_bytes())
}

fn hit(counts: Kv, res: Outgoing, name: Str) -> Result<(), Str> {
  let n = counts.add(name, 1);
  match n {
    Ok(v) => match reply(res, 200, json_entry(name, v)) {
      Ok(_) => Ok(()),
      Err(_) => Err("send"),
    },
    Err(_) => Err("kv"),
  }
}

fn count(counts: Kv, res: Outgoing, name: Str) -> Result<(), Str> {
  match read_count(counts, name) {
    Ok(v) => match reply(res, 200, json_entry(name, v)) {
      Ok(_) => Ok(()),
      Err(_) => Err("send"),
    },
    Err(_) => Err("kv"),
  }
}

fn top(counts: Kv, res: Outgoing) -> Result<(), Str> {
  let mut entries: List<Entry> = [];
  let mut after: Option<Str> = None;
  let mut more = true;
  while more {
    match counts.scan("", after, 1000) {
      Ok(page) => {
        for e in page {
          let c = e.value.to_str().parse_int().unwrap_or(0);
          entries.push(Entry { name: e.key, count: c });
        }
        if page.len() < 1000 {
          more = false;
        } else {
          after = Some(page[page.len() - 1].key);
        }
      }
      Err(_) => return Err("kv"),
    }
  }
  entries.sort_by(|a, b| a.count > b.count || (a.count == b.count && a.name < b.name));
  let mut parts: List<Str> = [];
  let mut i = 0;
  while i < entries.len() && i < 3 {
    parts.push(json_entry(entries[i].name, entries[i].count));
    i += 1;
  }
  let body = "[" + parts.join(", ") + "]";
  match reply(res, 200, body) {
    Ok(_) => Ok(()),
    Err(_) => Err("send"),
  }
}

fn not_found(res: Outgoing) -> Result<(), Str> {
  match reply(res, 404, "{\"error\": \"not found\"}") {
    Ok(_) => Ok(()),
    Err(_) => Err("send"),
  }
}

fn bad_name(res: Outgoing) -> Result<(), Str> {
  match reply(res, 400, "{\"error\": \"bad name\"}") {
    Ok(_) => Ok(()),
    Err(_) => Err("send"),
  }
}

fn route(req: Incoming, res: Outgoing, counts: Kv) -> Result<(), Str> {
  let method = req.method();
  let target = req.target();
  if method == "POST" && target.starts_with("/hit/") {
    let name = target.slice(5, target.len());
    if !valid_name(name) { return bad_name(res); }
    return hit(counts, res, name);
  }
  if method == "GET" && target.starts_with("/count/") {
    let name = target.slice(7, target.len());
    if !valid_name(name) { return bad_name(res); }
    return count(counts, res, name);
  }
  if method == "GET" && target == "/top" {
    return top(counts, res);
  }
  not_found(res)
}

fn main(req: Incoming, res: Outgoing, counts: Kv) -> Result<(), Str> {
  route(req, res, counts)
}

