struct Todo { id: Int, title: Str, done: Bool }
struct Reply { status: Int, body: Str }

fn reply(status: Int, j: Json) -> Reply {
  Reply { status: status, body: j.to_json() }
}

fn fail(status: Int, msg: Str) -> Reply {
  let mut m: Map<Str, Json> = Map::new();
  m.insert("error", Json::Str(msg));
  Reply { status: status, body: Json::Obj(m).to_json() }
}

fn not_found() -> Reply {
  fail(404, "not found")
}

fn todo_json(t: Todo) -> Json {
  let mut m: Map<Str, Json> = Map::new();
  m.insert("id", Json::Num(t.id));
  m.insert("title", Json::Str(t.title));
  m.insert("done", Json::Bool(t.done));
  Json::Obj(m)
}

fn todo_from(j: Json) -> Option<Todo> {
  let id = j.get("id")?.as_int()?;
  let title = j.get("title")?.as_str()?;
  let done = j.get("done")?.as_bool()?;
  Some(Todo { id: id, title: title, done: done })
}

fn decode(b: Bytes) -> Option<Todo> {
  let j = b.to_str().parse_json().ok()?;
  todo_from(j)
}

fn todo_key(id: Int) -> Str {
  "todo:" + id.to_str()
}

fn parse_id(s: Str) -> Option<Int> {
  let n = s.parse_int()?;
  if n.to_str() == s { Some(n) } else { None }
}

fn title_of(j: Json) -> Option<Str> {
  let t = j.get("title")?.as_str()?.trim();
  if t.len() == 0 { None } else { Some(t) }
}

fn load(store: Kv, id: Int) -> Result<Option<Todo>, KvErr> {
  let found = store.get(todo_key(id))?;
  Ok(found.and_then(decode))
}

fn create_todo(store: Kv, body: Bytes) -> Result<Reply, KvErr> {
  let Ok(j) = body.to_str().parse_json() else { return Ok(fail(400, "title required")); };
  let Some(title) = title_of(j) else { return Ok(fail(400, "title required")); };
  let id = store.add("next", 1)?;
  let t = Todo { id: id, title: title, done: false };
  store.set(todo_key(id), todo_json(t).to_json().to_bytes())?;
  Ok(reply(201, todo_json(t)))
}

fn list_todos(store: Kv, query: Str) -> Result<Reply, KvErr> {
  let keys = store.keys("todo:")?;
  let mut ids: List<Int> = keys.map(|k| k.slice(5, k.len()).parse_int().unwrap_or(0));
  ids.sort();
  let mut out: List<Json> = [];
  for id in ids {
    let found = load(store, id)?;
    let Some(t) = found else { continue; };
    if query == "done=true" && !t.done { continue; }
    if query == "done=false" && t.done { continue; }
    out.push(todo_json(t));
  }
  Ok(reply(200, Json::Arr(out)))
}

fn get_todo(store: Kv, id: Int) -> Result<Reply, KvErr> {
  let found = load(store, id)?;
  match found {
    Some(t) => Ok(reply(200, todo_json(t))),
    None => Ok(not_found()),
  }
}

fn patch_todo(store: Kv, id: Int, body: Bytes) -> Result<Reply, KvErr> {
  let found = load(store, id)?;
  let Some(old) = found else { return Ok(not_found()); };
  let Ok(j) = body.to_str().parse_json() else { return Ok(fail(400, "bad update")); };
  if j.as_map().is_none() { return Ok(fail(400, "bad update")); }
  let mut title = old.title;
  let mut done = old.done;
  if let Some(v) = j.get("title") {
    let Some(s) = v.as_str() else { return Ok(fail(400, "bad update")); };
    let t = s.trim();
    if t.len() == 0 { return Ok(fail(400, "bad update")); }
    title = t;
  }
  if let Some(v) = j.get("done") {
    let Some(b) = v.as_bool() else { return Ok(fail(400, "bad update")); };
    done = b;
  }
  let updated = Todo { id: old.id, title: title, done: done };
  store.set(todo_key(id), todo_json(updated).to_json().to_bytes())?;
  Ok(reply(200, todo_json(updated)))
}

fn delete_todo(store: Kv, id: Int) -> Result<Reply, KvErr> {
  let found = load(store, id)?;
  if found.is_none() { return Ok(not_found()); }
  store.delete(todo_key(id))?;
  Ok(Reply { status: 204, body: "" })
}

fn route(method: Str, target: Str, body: Bytes, store: Kv) -> Result<Reply, KvErr> {
  let parts = target.split("?");
  let query = if parts.len() > 1 { parts[1] } else { "" };
  let segs = parts[0].split("/");
  if segs.len() == 2 && segs[1] == "todos" {
    if method == "POST" { return create_todo(store, body); }
    if method == "GET" { return list_todos(store, query); }
    return Ok(not_found());
  }
  if segs.len() == 3 && segs[1] == "todos" {
    let Some(id) = parse_id(segs[2]) else { return Ok(not_found()); };
    if method == "GET" { return get_todo(store, id); }
    if method == "PATCH" { return patch_todo(store, id, body); }
    if method == "DELETE" { return delete_todo(store, id); }
  }
  Ok(not_found())
}

fn main(req: Incoming, res: Outgoing, store: Kv) -> Result<Str, WebErr> {
  let r = match route(req.method(), req.target(), req.body(), store) {
    Ok(r) => r,
    Err(_) => fail(500, "store failed"),
  };
  if r.body.len() == 0 {
    res.send(r.status, [], [], "".to_bytes())?;
  } else {
    res.send(r.status, ["content-type"], ["application/json"], r.body.to_bytes())?;
  }
  Ok("sent")
}

struct Reply { status: Int, body: Str }

fn not_found() -> Reply {
  Reply { status: 404, body: "{\"error\": \"not found\"}" }
}

fn invalid() -> Reply {
  Reply { status: 400, body: "{\"error\": \"invalid note\"}" }
}

fn setup(db: Db) -> Result<(), DbErr> {
  db.exec("CREATE TABLE IF NOT EXISTS notes (id INTEGER PRIMARY KEY AUTOINCREMENT, title TEXT NOT NULL, body TEXT NOT NULL)", [])?;
  db.exec("CREATE TABLE IF NOT EXISTS note_tags (note_id INTEGER NOT NULL REFERENCES notes(id) ON DELETE CASCADE, tag TEXT NOT NULL, pos INTEGER NOT NULL, PRIMARY KEY (note_id, tag))", [])?;
  db.exec("CREATE INDEX IF NOT EXISTS note_tags_tag ON note_tags (tag)", [])?;
  Ok(())
}

fn create_note(req: Incoming, db: Db) -> Result<Reply, DbErr> {
  let text = req.body().to_str();
  let Ok(j) = text.parse_json() else { return Ok(invalid()); };
  let Some(title) = j.get("title").and_then(|v| v.as_str()) else { return Ok(invalid()); };
  let Some(body) = j.get("body").and_then(|v| v.as_str()) else { return Ok(invalid()); };
  if title.len() == 0 { return Ok(invalid()); }
  let mut tags: List<Str> = [];
  if let Some(v) = j.get("tags") {
    let Some(items) = v.as_list() else { return Ok(invalid()); };
    for it in items {
      let Some(t) = it.as_str() else { return Ok(invalid()); };
      let lower = t.to_lowercase();
      if !tags.contains(lower) { tags.push(lower); }
    }
  }
  let rid = db.query("INSERT INTO notes (title, body) VALUES (?, ?) RETURNING id", [SqlValue::Text(title), SqlValue::Text(body)])?;
  let row = rid[0];
  let SqlValue::Int(id) = row[0] else { return Ok(invalid()); };
  let mut stmts: List<Str> = [];
  let mut args: List<List<SqlValue>> = [];
  for i in 0..tags.len() {
    stmts.push("INSERT INTO note_tags (note_id, tag, pos) VALUES (?, ?, ?)");
    args.push([SqlValue::Int(id), SqlValue::Text(tags[i]), SqlValue::Int(i)]);
  }
  if stmts.len() > 0 { db.transaction(stmts, args)?; }
  Ok(Reply { status: 201, body: "{\"id\": " + id.to_str() + "}" })
}

fn note_json(id: Int, db: Db) -> Result<Option<Json>, DbErr> {
  let rows = db.query("SELECT title, body FROM notes WHERE id = ?", [SqlValue::Int(id)])?;
  if rows.len() == 0 { return Ok(None); }
  let row = rows[0];
  let SqlValue::Text(title) = row[0] else { return Ok(None); };
  let SqlValue::Text(body) = row[1] else { return Ok(None); };
  let tag_rows = db.query("SELECT tag FROM note_tags WHERE note_id = ? ORDER BY pos", [SqlValue::Int(id)])?;
  let mut tags: List<Json> = [];
  for r in tag_rows {
    let SqlValue::Text(t) = r[0] else { return Ok(None); };
    tags.push(Json::Str(t));
  }
  let mut m: Map<Str, Json> = Map::new();
  m.insert("id", Json::Num(id));
  m.insert("title", Json::Str(title));
  m.insert("body", Json::Str(body));
  m.insert("tags", Json::Arr(tags));
  Ok(Some(Json::Obj(m)))
}

fn get_note(id: Int, db: Db) -> Result<Reply, DbErr> {
  match note_json(id, db)? {
    None => Ok(not_found()),
    Some(j) => Ok(Reply { status: 200, body: j.to_json() }),
  }
}

fn delete_note(id: Int, db: Db) -> Result<Reply, DbErr> {
  let n = db.exec("DELETE FROM notes WHERE id = ?", [SqlValue::Int(id)])?;
  if n == 0 { return Ok(not_found()); }
  Ok(Reply { status: 200, body: "{\"deleted\": " + id.to_str() + "}" })
}

fn query_value(query: Str, key: Str) -> Option<Str> {
  for pair in query.split("&") {
    let kv = pair.split("=");
    if kv.len() == 2 && kv[0] == key { return Some(kv[1]); }
  }
  None
}

fn list_notes(query: Str, db: Db) -> Result<Reply, DbErr> {
  let has_tag = if query_value(query, "tag").is_some() { 1 } else { 0 };
  let tag = query_value(query, "tag").unwrap_or("").to_lowercase();
  let has_q = if query_value(query, "q").is_some() { 1 } else { 0 };
  let word = query_value(query, "q").unwrap_or("");
  let rows = db.query("SELECT id, title FROM notes WHERE (? = 0 OR EXISTS (SELECT 1 FROM note_tags t WHERE t.note_id = notes.id AND t.tag = ?)) AND (? = 0 OR instr(title, ?) > 0 OR instr(body, ?) > 0) ORDER BY id DESC", [SqlValue::Int(has_tag), SqlValue::Text(tag), SqlValue::Int(has_q), SqlValue::Text(word), SqlValue::Text(word)])?;
  let mut items: List<Json> = [];
  for r in rows {
    let SqlValue::Int(id) = r[0] else { continue; };
    let SqlValue::Text(title) = r[1] else { continue; };
    let mut m: Map<Str, Json> = Map::new();
    m.insert("id", Json::Num(id));
    m.insert("title", Json::Str(title));
    items.push(Json::Obj(m));
  }
  Ok(Reply { status: 200, body: Json::Arr(items).to_json() })
}

fn route(req: Incoming, db: Db) -> Result<Reply, DbErr> {
  let method = req.method();
  let parts = req.target().split("?");
  let path = parts[0];
  let query = if parts.len() > 1 { parts[1] } else { "" };
  let segs = path.split("/");
  if segs.len() == 2 && segs[1] == "notes" {
    if method == "POST" { return create_note(req, db); }
    if method == "GET" { return list_notes(query, db); }
    return Ok(not_found());
  }
  if segs.len() == 3 && segs[1] == "notes" {
    let Some(id) = segs[2].parse_int() else { return Ok(not_found()); };
    if method == "GET" { return get_note(id, db); }
    if method == "DELETE" { return delete_note(id, db); }
  }
  Ok(not_found())
}

fn answer(req: Incoming, db: Db) -> Result<Reply, DbErr> {
  setup(db)?;
  route(req, db)
}

fn main(req: Incoming, res: Outgoing, db: Db) -> Result<Str, WebErr> {
  let reply = match answer(req, db) {
    Ok(r) => r,
    Err(_) => Reply { status: 500, body: "{\"error\": \"internal error\"}" },
  };
  res.send(reply.status, ["content-type"], ["application/json"], reply.body.to_bytes())?;
  Ok("ok")
}

struct Station { id: Str, name: Str }

// Tenths of a degree to "D.F", e.g. -5 -> "-0.5", 123 -> "12.3".
fn fmt_tenths(t: Int) -> Str {
  let neg = t < 0;
  let a = if neg { 0 - t } else { t };
  let sign = if neg { "-" } else { "" };
  sign + (a / 10).to_str() + "." + (a % 10).to_str()
}

fn station_list(body: Bytes) -> Option<List<Station>> {
  let doc = body.to_str().parse_json().ok()?;
  let items = doc.get("stations")?.as_list()?;
  let mut out: List<Station> = [];
  for s in items {
    out.push(Station { id: s.get("id")?.as_str()?, name: s.get("name")?.as_str()? });
  }
  Some(out)
}

fn temps(body: Bytes) -> Option<List<Int>> {
  let doc = body.to_str().parse_json().ok()?;
  let rs = doc.get("readings")?.as_list()?;
  let mut out: List<Int> = [];
  for r in rs {
    out.push(r.get("temp")?.as_int()?);
  }
  Some(out)
}

fn station_line(api: Http, s: Station) -> Str {
  let Ok(body) = api.get("/stations/" + s.id + "/readings") else {
    return s.name + " unavailable";
  };
  let Some(ts) = temps(body) else {
    return s.name + " unavailable";
  };
  let n = ts.len();
  if n == 0 {
    return s.name + " no data";
  }
  let mut lo = ts[0];
  let mut hi = ts[0];
  let mut sum = 0;
  for t in ts {
    lo = lo.min(t);
    hi = hi.max(t);
    sum = sum + t;
  }
  let avg = sum / n;
  s.name + " min=" + fmt_tenths(lo) + " max=" + fmt_tenths(hi)
    + " avg=" + fmt_tenths(avg) + " n=" + n.to_str()
}

fn main(api: Http) -> Result<Str, Str> {
  let Ok(body) = api.get("/stations") else {
    return Err("stations unavailable");
  };
  let Some(list) = station_list(body) else {
    return Err("stations: bad JSON");
  };
  let mut ss = list;
  ss.sort_by_key(|s| s.name);
  let mut lines: List<Str> = [];
  for s in ss {
    lines.push(station_line(api, s));
  }
  Ok(lines.join("\n"))
}

fn fetch_page(api: Http, page: Int) -> Result<Json, Str> {
  let r = api.get("/orders?page=" + page.to_str())
    .map_err(|e| "GET failed")?;
  let text = r.to_str();
  text.parse_json()
}

fn main(api: Http) -> Result<Str, Str> {
  let mut orders_count: Int = 0;
  let mut paid_cents: Map<Str, Int> = Map::new();
  let mut refunded: Int = 0;
  let mut largest_id: Int = 0;
  let mut largest_cents: Int = -1;
  let mut page: Int = 1;

  loop {
    let doc = fetch_page(api, page)?;
    let items = doc.get("orders").and_then(|j| j.as_list()).unwrap_or([]);
    for o in items {
      orders_count = orders_count + 1;
      let status = o.get("status").and_then(|j| j.as_str()).unwrap_or("");
      let cents = o.get("cents").and_then(|j| j.as_int()).unwrap_or(0);
      let id = o.get("id").and_then(|j| j.as_int()).unwrap_or(0);
      let currency = o.get("currency").and_then(|j| j.as_str()).unwrap_or("");
      if status == "paid" {
        let prev = paid_cents.get(currency).unwrap_or(0);
        paid_cents.insert(currency, prev + cents);
        if cents > largest_cents || (cents == largest_cents && id < largest_id) {
          largest_cents = cents;
          largest_id = id;
        }
      }
      if status == "refunded" {
        refunded = refunded + 1;
      }
    }
    let next = doc.get("next").and_then(|j| j.as_int());
    if next.is_none() {
      break;
    }
    page = next.unwrap_or(page);
  }

  let mut eur: Int = paid_cents.get("EUR").unwrap_or(0);
  let mut usd: Int = paid_cents.get("USD").unwrap_or(0);

  let mut currency_parts: List<Str> = [];
  for c in paid_cents.keys() {
    let v = paid_cents.get(c).unwrap_or(0);
    currency_parts.push("\"" + c + "\": " + v.to_str());
  }
  let paid_json = "{" + currency_parts.join(", ") + "}";

  let body = "{\"orders\": " + orders_count.to_str()
    + ", \"paid_cents\": " + paid_json
    + ", \"refunded\": " + refunded.to_str()
    + ", \"largest\": " + largest_id.to_str() + "}";

  let r = api.send("POST", "/summaries", ["content-type: application/json"], body.to_bytes())
    .map_err(|e| "POST failed")?;
  if r.status != 201 {
    return Err("summary POST answered " + r.status.to_str());
  }
  let resp = r.body.to_str();
  let parsed = resp.parse_json()?;
  let id = parsed.get("id").and_then(|j| j.as_str()).unwrap_or("");
  Ok(id)
}
